import{_ as o,C as s,o as n,c as i,a3 as c,E as l,w as d,j as t,a as r}from"./chunks/framework.MpnVSsqk.js";const p="/versions/v0.16.12/screens/projects/projects_menu.png",h="/versions/v0.16.12/screens/projects/migrate_all_confirm.png",g="/versions/v0.16.12/screens/projects/migrate_all_progress.png",m="/versions/v0.16.12/screens/projects/migrate_all_summary.png",y=JSON.parse('{"title":"Projects","description":"","frontmatter":{},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md"}'),u={name:"projects/index.md"};function j(f,e,v,b,w,P){const a=s("ManualRelated");return n(),i("div",null,[e[1]||(e[1]=c('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><p>A <strong>project</strong> is a complete saved setup: all 32 knobs, macros, up to eight racks, LFOs, and snapshots.</p><h2 id="projects-menu" tabindex="-1">Projects menu <a class="header-anchor" href="#projects-menu" aria-label="Permalink to &quot;Projects menu&quot;">​</a></h2><p><img src="'+p+'" alt="Projects menu" class="screen"></p><p>Rows that open another screen show a <strong>three-line list</strong> icon on the right; <strong>Save Project</strong>, <strong>Rename Project</strong>, and <strong>Migrate All Projects</strong> show a <strong>ring and dot</strong> icon because Select runs the action immediately.</p><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><a href="./list">Projects List</a></td><td>Browse, load, create, rename, save as, or delete projects</td></tr><tr><td>Save Project</td><td>Save the active project (shown when there are unsaved changes)</td></tr><tr><td>Rename Project</td><td>Rename the <strong>active</strong> project</td></tr><tr><td><a href="#migrate-all-projects">Migrate All Projects</a></td><td>Update every out-of-date project on internal storage and microSD in one pass</td></tr></tbody></table><h2 id="manual-save" tabindex="-1">Manual save <a class="header-anchor" href="#manual-save" aria-label="Permalink to &quot;Manual save&quot;">​</a></h2><p>Most edits — macros, racks, LFO wiring, device parameters — are kept in memory until you <strong>Save Project</strong>. Use <strong>Save Project</strong> before power-off if you want those changes back next time.</p><p>Switching to another project while you still have unsaved edits may show a prompt — save, discard, or cancel.</p><h2 id="migrate-all-projects" tabindex="-1">Migrate All Projects <a class="header-anchor" href="#migrate-all-projects" aria-label="Permalink to &quot;Migrate All Projects&quot;">​</a></h2><p>After a firmware update, projects saved by the previous firmware version are still on your S32 but are stored in the older format. Loading one asks <strong>Update project to current version?</strong> and updates just that project. <strong>Migrate All Projects</strong> does the same for every out-of-date project at once, across <strong>internal storage and microSD</strong>.</p><p>Select it and the S32 first checks each project, then asks how many it is about to update.</p><p><img src="'+h+'" alt="Migrate All Projects confirmation" class="screen"></p><p>Press <strong>OK</strong> to start, or <strong>Back</strong> to leave everything untouched. If the active project has unsaved edits you are asked to save or discard them first.</p><p>A progress bar tracks the batch and blocks the controls until it finishes.</p><p><img src="'+g+'" alt="Migrate All Projects progress" class="screen"></p><p>When it finishes, a summary shows what happened.</p><p><img src="'+m+'" alt="Migrate All Projects summary" class="screen"></p><table tabindex="0"><thead><tr><th>Count</th><th>Meaning</th></tr></thead><tbody><tr><td>Updated</td><td>Projects rewritten in the current format</td></tr><tr><td>Skipped</td><td>Too old or too new to update (see below) — projects that were already up to date are not counted here</td></tr><tr><td>Failed</td><td>Could not be read or written — the original project is left as it was</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Projects that cannot be updated</p><p>The S32 only updates projects saved by the <strong>immediately previous</strong> firmware version.</p><ul><li><strong>Project needs older firmware first</strong> — saved by a much older firmware. Install the intermediate firmware version, open the project once so it updates, then return to the current firmware.</li><li><strong>Project needs newer firmware</strong> — saved by a firmware version newer than the one installed. Update the S32 firmware.</li></ul><p>Both are reported as <em>skipped</em>; nothing is written to them.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Leave the microSD card inserted for the whole batch — projects on a card that is removed part-way are reported as failed and stay in the old format.</li><li>Nothing is deleted. Projects are rewritten in place, keeping their name, storage location, and contents.</li><li>Running the action again is safe; projects already updated are simply skipped.</li></ul></div><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Racks per project</td><td>Up to <strong>8</strong></td></tr><tr><td>Project name length</td><td>Up to <strong>15</strong> characters</td></tr></tbody></table><p>You can store as many projects as your storage allows. Open <strong>Settings → Storage Info</strong> to see how much space is left. If save fails, see <a href="./../getting-started/troubleshooting">Troubleshooting</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Save Project</strong> — structure or mapping changed and you want it after power cycle.</li><li><strong>Snapshots</strong> — quick scene recall within one project (see <a href="./../snapshots/">Snapshots</a> — full guide coming soon).</li></ul></div>',25)),l(a,null,{default:d(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"./list"},"Projects List"),r(" — Create, load, rename, save as, delete")]),t("li",null,[t("a",{href:"./../concepts/projects-and-snapshots"},"Projects & snapshots concept"),r(" — What projects store")]),t("li",null,[t("a",{href:"./../getting-started/troubleshooting"},"Troubleshooting"),r(" — Save and storage messages")])],-1)])]),_:1})])}const k=o(u,[["render",j]]);export{y as __pageData,k as default};
